import type { CapacitorConfig } from "@capacitor/cli";

// Lantern mobile: Capacitor remote client for the Lantern dashboard.
// The web app lives in www/ (generated by scripts/sync-web.sh from
// the Python dashboard plus the mobile client in src/). Scanning
// stays server-side, on the Lantern server at home. See
// docs/ADR-001-mobile-architecture.md for the decision record.
//
// CapacitorHttp is enabled so API calls to the home server go through
// the native layer and bypass the browser CORS check. The Lantern
// server is same-origin only and sends no CORS headers, so plain
// fetch from the app WebView would be blocked. See src/api.js.
const config: CapacitorConfig = {
  appId: "com.beardlab.lantern",
  appName: "Lantern",
  webDir: "www",
  plugins: {
    CapacitorHttp: {
      enabled: true,
    },
  },
};

export default config;
